    pick: async (rx, ms = 15000) => { const end = Date.now() + ms; while (Date.now() < end) { const d = t.minigame.getState() && t.minigame.getState().dialogue; if (d && d.awaitingChoice && (d.choices || []).some(c => new RegExp(rx, 'i').test(c.text))) { const r = await t.minigame.choose(rx); return !(r && r.ok === false); } if (d && d.canContinue) await t.minigame.continue(); await new Promise(r => setTimeout(r, 150)); } return false; },
