async () => { /* A7 Go in: case closes; the debrief opens after the call */ if (!(await window.__ded.call('HaX'))) return false; if (!(await window.__ded.pick('^I.m ready to go into the sanctum'))) return false; if (!(await window.__ded.pick('^Go in'))) return false;
  const end = Date.now() + 20000; while (Date.now() < end) { const d = window.__ded.board(); if (d && d.view === 'debrief') break; const s = window.__test.minigame.getState(); if (s && s.dialogue && s.dialogue.canContinue) await window.__test.minigame.continue(); await new Promise(r => setTimeout(r, 200)); }
  return window.__ded.g().deduction_closed === true && window.__ded.board().view === 'debrief'; }

async () => { /* A7 debrief: Marsh missed_guilty, Not named, with the clue that would have settled it and its place 'Marsh's favour' (or already held, if decided at close); no-blame line chosen; the acolyte not yet revealed */ const d = window.__ded.board().debrief; const m = d.cards.find(c => c.id === 'ded_a_marsh'); const txt = window.MinigameFramework.currentMinigame.container.textContent;
  const where = JSON.stringify(m.settling || m.alreadyHeld || {});
  return m.outcome === 'missed_guilty' && m.verdictKind === 'none' && (/Marsh's favour/.test(where) || !!m.alreadyHeld) && /Not named/.test(txt) && ['misread','missed','notActed'].includes(d.noBlame)
    && !window.npcHostileSystem.isNPCHostile('ded_a_acolyte'); }

async () => { /* A7 Finish: the solved task is skipped, a_case_closed set, the evening does NOT end here (a_left_early false), and the acolyte waits in pendingHostiles for the sanctum to load */ await new Promise(r => setTimeout(r, 2500)); const g = window.__ded.g(); const r = window.__ded.rt();
  const t = window.objectivesManager.taskIndex && window.objectivesManager.taskIndex.a_case_solved;
  return g.a_case_closed === true && g.a_ending === false && (!t || t.status === 'skipped') && r.state.pendingHostiles.some(p => p.id === 'ded_a_acolyte' && p.room === 'a_sanctum'); }
